function validate([n, nums, maxDiff, queries]) {
  if (n < 1 || n > 100000 || nums.length !== n) return 'nums must hold exactly n values, with 1 <= n <= 10^5.';
  if (nums.some(v => v < 0 || v > 100000)) return 'Each value of nums is between 0 and 10^5.';
  for (let i = 1; i < n; i++) if (nums[i] < nums[i - 1]) return 'nums must be sorted in non-decreasing order.';
  if (maxDiff < 0 || maxDiff > 100000) return 'maxDiff is between 0 and 10^5.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 pairs.';
  if (queries.some(q => q.length !== 2 || q.some(x => x < 0 || x >= n))) return 'Each query is [u, v] with 0 <= u, v < n.';
  return null;
}

