function pathExistenceQueries(n, nums, maxDiff, queries) {
  // Build every edge of the graph explicitly, then search outward from u for each query.
  const neighbors = [];
  for (let i = 0; i < n; i++) {
    neighbors.push([]);
    for (let j = 0; j < n; j++) if (i !== j && Math.abs(nums[i] - nums[j]) <= maxDiff) neighbors[i].push(j);
  }
  return queries.map(([u, v]) => {
    const seen = new Set([u]);
    const stack = [u];
    while (stack.length) {
      const node = stack.pop();
      for (const next of neighbors[node]) if (!seen.has(next)) { seen.add(next); stack.push(next); }
    }
    return seen.has(v);
  });
}

