function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 8);
  const maxDiff = large ? int(20, 40) : int(0, 3);
  const nums = [int(0, large ? 100 : 5)];
  for (let i = 1; i < n; i++) {
    // Mostly steps within maxDiff that keep neighbours joined, with occasional jumps that split the graph.
    const step = rand() < (large ? 0.02 : 0.3) ? maxDiff + int(1, large ? 50 : 3) : int(0, maxDiff);
    nums.push(Math.min(100000, nums[i - 1] + step));
  }
  const count = large ? 2000 : int(1, 6);
  const queries = Array.from({ length: count }, () => [int(0, n - 1), int(0, n - 1)]);
  return [n, nums, maxDiff, queries];
}
